arguments.command:
cd /app/submission && python3 - <<'PYEOF'
s=open('planner.py').read()
s=s.replace('RESPONSE_BUDGET = 95.0        # wall seconds for one request',
            'RESPONSE_BUDGET = 90.0        # wall seconds for one request')
s=s.replace('STEP_LIMIT = 25.0             # wall seconds for one solver call',
            'STEP_LIMIT = 20.0             # wall seconds for one solver call')
# handle(): safer gating
hstart = s.index("def handle(req):")
hend = s.index("# --------------------------------------------------------------------------\n# line protocol")
new = '''def handle(req):
    _DEADLINE[0] = time.time() + RESPONSE_BUDGET
    prob = Problem(req)
    state, x, y, q, resid = solve_primal(prob)
    if state in ("optimal", "weak"):
        xc, t, loads, mlu, migration = primal_from_flows(prob, x)
        y, q = _pick_duals(prob, [(y, q), solve_dual_lp(prob)], mlu)
        if state == "optimal":
            return response_optimal(prob, req["epoch"], xc, y, q, mlu,
                                    migration, loads)
    if state == "infeasible":
        fy, fq, _ok = solve_infeasible(prob)
        if fy is not None:
            return response_infeasible(req["epoch"], fy, fq)
        sys.stderr.write("infeasible without witness\\n")
        return {"status": "invalid"}
    if state == "unknown":
        fy, fq, ok = solve_infeasible(prob)
        if ok:
            return response_infeasible(req["epoch"], fy, fq)
        sys.stderr.write("unsolved request\\n")
        return {"status": "invalid"}
    # doubtful primal: only trust a witness that passes the tight gate
    if state == "weak":
        if resid <= 5e-6:
            xc, t, loads, mlu, migration = primal_from_flows(prob, x)
            return response_optimal(prob, req["epoch"], xc, y, q, mlu,
                                    migration, loads)
        fy, fq, ok = solve_infeasible(prob)
        if ok:
            return response_infeasible(req["epoch"], fy, fq)
        xc, t, loads, mlu, migration = primal_from_flows(prob, x)
        return response_optimal(prob, req["epoch"], xc, y, q, mlu,
                                migration, loads)
    sys.stderr.write("unreachable state %s\\n" % (state,))
    return {"status": "invalid"}


'''
s = s[:hstart] + new + s[hend:]
open('planner.py','w').write(s)
PYEOF
python3 -c "import ast;ast.parse(open('/app/submission/planner.py').read())" && cd /app/work && bash all.sh 2>&1 | tail -10 && python3 /app/submission/planner.py < oneshot.jsonl
